  if(unlimitedStepsGraphCache)return unlimitedStepsGraphCache;const buckets=new Map();for(const w of WORD_STEPS_DICTIONARY)for(let i=0;i<4;i++){const k=w.slice(0,i)+'*'+w.slice(i+1);if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(w)}const neighbors=new Map(WORD_STEPS_DICTIONARY.map(w=>[w,new Set()]));for(const vals of buckets.values())for(const w of vals)for(const v of vals)if(v!==w)neighbors.get(w).add(v);unlimitedStepsGraphCache=neighbors;return neighbors;
