  if(id.startsWith('state_initial_'))return `U.S. states beginning with ${letter}`;if(id.startsWith('country_initial_'))return `Countries beginning with ${letter}`;if(id.startsWith('element_initial_'))return `Chemical elements beginning with ${letter}`;if(id.startsWith('capital_initial_'))return `U.S. state capitals beginning with ${letter}`;if(id.startsWith('constellation_initial_'))return `Constellations beginning with ${letter}`;if(id.startsWith('play_initial_'))return `Shakespeare plays beginning with ${letter}`;if(id.startsWith('country_range_'))return `Countries beginning with ${range.split('').join('–')}`;if(id.startsWith('element_range_'))return `Chemical elements beginning with ${range.split('').join('–')}`;if(id.startsWith('constellation_range_'))return `Constellations beginning with ${range.split('').join('–')}`;
