  if(game==='link'&&path==='/api/unlimited/link/guess'){const guess=normalizeWord(b.guess),attempt=Math.max(1,Number(b.attempt)||1),solved=guess===p.link.answer;return json({ok:true,solved,...(solved||attempt>=3?{answer:p.link.answer,note:p.link.note}:{})})}if(game==='link'&&path==='/api/unlimited/link/reveal'){if(Number(b.guesses)<3)return json({error:'The answer is revealed after three guesses.'},403);return json({ok:true,answer:p.link.answer,note:p.link.note})}
